@startuml

class Scene {
  + code : string
  + description : string
}

class Setup {
  + code : string
  + photographic_parameters : string
}

class Take {
  + nbr : int
  + film_meters : double
  + reel_code : string
}

class Internal extends Scene {
  + theater : string
}

class External extends Scene {
  + location : Location
}

class Location {
  + code : string
  + address : string
  + description : string
}

Scene "1" *-- "1..*" Setup
Setup "1" *-- "1..*" Take
External "1" -- "1" Location

@enduml

